/**
 * routeRegistry contract tests.
 *
 * `routeRegistry.ts` is AUTOGENERATED from `App.tsx` by
 * `web/scripts/generate-route-registry.mjs` and is the single source of
 * truth consumed by:
 *   - the 404 suggestion engine (`closestRoute.ts`)
 *   - breadcrumb metadata (`routeMeta.ts`)
 *   - recent-page label resolution (`recentPages.ts`)
 *   - the sidebar / command palette
 *
 * Because it is generated, the two failure modes we actually care about are
 * (a) the committed file drifting out of sync with `App.tsx` (routes added to
 * the app but never regenerated here — the exact bug this suite was written
 * to catch) and (b) a well-meaning hand-edit silently breaking the invariants
 * downstream consumers rely on. Both are covered below.
 *
 * The parsing in the drift guard mirrors the generator's regexes and dedup
 * rules verbatim, so "expected" is by construction identical to what a fresh
 * `node scripts/generate-route-registry.mjs` run would emit.
 */

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { ROUTE_REGISTRY, type RouteEntry } from './routeRegistry'

// ── Generator-mirrored helpers ────────────────────────────────────────────
// Copied byte-for-byte from generate-route-registry.mjs so these tests encode
// the generator's contract rather than a re-interpretation of it.

/** "BatteryHealth" → "Battery Health", "MQTTInspector" → "MQTT Inspector". */
function humanize(s: string): string {
  return s
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .trim()
}

function lowerFirst(s: string): string {
  return s.charAt(0).toLowerCase() + s.slice(1)
}

/**
 * Re-derive the (path → name) map the generator would produce from the
 * current `App.tsx`. Mirrors the generator's regexes, `*`-skip, leading-slash
 * normalization, and first-wins dedup exactly.
 */
function parseAppRoutes(src: string): Map<string, string> {
  const RE_PATH = /<Route\s+path="([^"]+)"\s+element=\{<SafeRoute\s+name="([^"]+)"/g
  const RE_INDEX = /<Route\s+index\s+element=\{<SafeRoute\s+name="([^"]+)"/g
  const byPath = new Map<string, string>()

  let m: RegExpExecArray | null
  while ((m = RE_PATH.exec(src)) !== null) {
    const rawPath = m[1]
    const name = m[2]
    if (rawPath === '*') continue
    const path = rawPath.startsWith('/') ? rawPath : '/' + rawPath
    if (!byPath.has(path)) byPath.set(path, name)
  }
  while ((m = RE_INDEX.exec(src)) !== null) {
    const name = m[1]
    const path = '/'
    if (!byPath.has(path)) byPath.set(path, name)
  }
  return byPath
}

const APP_SRC = readFileSync(
  resolve(dirname(fileURLToPath(import.meta.url)), '..', 'App.tsx'),
  'utf8',
)

const actualByPath = new Map<string, string>(
  ROUTE_REGISTRY.map((r) => [r.path, r.name] as [string, string]),
)

describe('ROUTE_REGISTRY — structural contract', () => {
  it('is a non-empty array of route entries', () => {
    expect(Array.isArray(ROUTE_REGISTRY)).toBe(true)
    expect(ROUTE_REGISTRY.length).toBeGreaterThan(0)
  })

  it('every entry carries non-empty string path/name/label/i18nKey', () => {
    const bad = ROUTE_REGISTRY.filter(
      (r) =>
        typeof r.path !== 'string' ||
        typeof r.name !== 'string' ||
        typeof r.label !== 'string' ||
        typeof r.i18nKey !== 'string' ||
        r.path.length === 0 ||
        r.name.length === 0 ||
        r.label.length === 0 ||
        r.i18nKey.length === 0,
    )
    expect(bad, `malformed entries: ${bad.map((r) => r.path).join(', ')}`).toEqual([])
  })

  it('only ever sets `hidden` to a boolean (or omits it)', () => {
    for (const r of ROUTE_REGISTRY) {
      expect(['boolean', 'undefined']).toContain(typeof r.hidden)
    }
  })

  it('every path is absolute (starts with "/")', () => {
    const relative = ROUTE_REGISTRY.filter((r) => !r.path.startsWith('/')).map((r) => r.path)
    expect(relative).toEqual([])
  })

  it('uses `path` as the primary key — no duplicate paths', () => {
    const paths = ROUTE_REGISTRY.map((r) => r.path)
    const dupes = paths.filter((p, i) => paths.indexOf(p) !== i)
    expect(dupes, `duplicate paths: ${[...new Set(dupes)].join(', ')}`).toEqual([])
    expect(new Set(paths).size).toBe(ROUTE_REGISTRY.length)
  })
})

describe('ROUTE_REGISTRY — generator invariants (guards hand-edits)', () => {
  it('derives `label` from the SafeRoute `name` via humanize()', () => {
    // This is the invariant a hand-edit most easily breaks — e.g. relabeling
    // "/notifications/audit" to "Audit Log" instead of "Notifications Audit".
    const mismatched = ROUTE_REGISTRY.filter((r) => r.label !== humanize(r.name)).map(
      (r) => `${r.path}: "${r.label}" !== humanize("${r.name}")="${humanize(r.name)}"`,
    )
    expect(mismatched).toEqual([])
  })

  it('derives `i18nKey` as "routes." + lowerFirst(name)', () => {
    const mismatched = ROUTE_REGISTRY.filter(
      (r) => r.i18nKey !== 'routes.' + lowerFirst(r.name),
    ).map((r) => `${r.path}: "${r.i18nKey}"`)
    expect(mismatched).toEqual([])
  })

  it('hides exactly the parameterized (":") routes and nothing else', () => {
    const wrong = ROUTE_REGISTRY.filter(
      (r) => Boolean(r.hidden) !== r.path.includes(':'),
    ).map((r) => `${r.path} (hidden=${String(r.hidden)})`)
    expect(wrong, `hidden flag disagrees with param-ness: ${wrong.join(', ')}`).toEqual([])

    // Sanity: the split is non-trivial (there is at least one of each).
    expect(ROUTE_REGISTRY.some((r) => r.hidden)).toBe(true)
    expect(ROUTE_REGISTRY.some((r) => !r.hidden)).toBe(true)
  })

  it('never stores `hidden: false` explicitly (omitted when visible)', () => {
    // The generator writes `hidden: true` or omits the key entirely, so a
    // literal `false` would signal a hand-edit.
    expect(ROUTE_REGISTRY.some((r) => r.hidden === false)).toBe(false)
  })

  it('excludes the catch-all "*" route and the NotFound page', () => {
    expect(ROUTE_REGISTRY.some((r) => r.path === '*')).toBe(false)
    expect(ROUTE_REGISTRY.some((r) => r.name === 'NotFound')).toBe(false)
  })

  it('is sorted by path ascending (localeCompare)', () => {
    const paths = ROUTE_REGISTRY.map((r) => r.path)
    const sorted = [...paths].sort((a, b) => a.localeCompare(b))
    expect(paths).toEqual(sorted)
  })
})

describe('ROUTE_REGISTRY — alias & consumer contract', () => {
  it('keeps label + i18nKey consistent across name aliases', () => {
    // A `name` may legitimately map to several path aliases (e.g. both
    // "/tco" and "/analytics/tco" resolve to TrueCostOwnership). When it
    // does, every alias MUST share the same label + i18nKey, because those
    // are pure functions of the name.
    const byName = new Map<string, RouteEntry[]>()
    for (const r of ROUTE_REGISTRY) {
      const group = byName.get(r.name) ?? []
      group.push(r)
      byName.set(r.name, group)
    }
    const inconsistent: string[] = []
    for (const [name, group] of byName) {
      const label = group[0].label
      const key = group[0].i18nKey
      if (group.some((r) => r.label !== label || r.i18nKey !== key)) {
        inconsistent.push(name)
      }
    }
    expect(inconsistent, `inconsistent aliases: ${inconsistent.join(', ')}`).toEqual([])
  })

  it('exposes only navigable (non-parameterized) routes to suggestion/palette UIs', () => {
    // Consumers like closestRoutes() filter on `hidden`; a visible route that
    // still needs a param would produce an un-navigable suggestion.
    const navigable = ROUTE_REGISTRY.filter((r) => !r.hidden)
    expect(navigable.every((r) => !r.path.includes(':'))).toBe(true)
    expect(navigable.length).toBeGreaterThan(0)
  })

  it('contains the dashboard root and core visible routes', () => {
    const dashboard = actualByPath.get('/')
    expect(dashboard).toBe('Dashboard')

    for (const p of ['/vehicles', '/charging', '/drives', '/settings']) {
      const entry = ROUTE_REGISTRY.find((r) => r.path === p)
      expect(entry, `missing core route ${p}`).toBeDefined()
      expect(entry?.hidden ?? false).toBe(false)
    }
  })
})

describe('ROUTE_REGISTRY — in sync with App.tsx (drift guard)', () => {
  const expectedByPath = parseAppRoutes(APP_SRC)

  it('sanity: parsed App.tsx yields a plausible route set', () => {
    // Guards against a broken read/regex silently producing an empty map,
    // which would make the drift assertions vacuously pass.
    expect(expectedByPath.size).toBeGreaterThan(50)
    expect(expectedByPath.get('/')).toBe('Dashboard')
  })

  it('contains every <SafeRoute> route declared in App.tsx (no missing)', () => {
    const missing: string[] = []
    for (const [path, name] of expectedByPath) {
      if (actualByPath.get(path) !== name) {
        missing.push(`${path} → ${name} (registry has ${String(actualByPath.get(path))})`)
      }
    }
    expect(
      missing,
      `registry is stale — re-run \`node scripts/generate-route-registry.mjs\`: ${missing.join('; ')}`,
    ).toEqual([])
  })

  it('contains no routes absent from App.tsx (no extras)', () => {
    const extras = [...actualByPath.keys()].filter((p) => !expectedByPath.has(p))
    expect(extras, `registry has orphaned routes: ${extras.join(', ')}`).toEqual([])
  })

  it('matches App.tsx exactly on path→name mapping and count', () => {
    expect(actualByPath.size).toBe(expectedByPath.size)
    expect(
      Object.fromEntries([...actualByPath].sort(([a], [b]) => a.localeCompare(b))),
    ).toEqual(Object.fromEntries([...expectedByPath].sort(([a], [b]) => a.localeCompare(b))))
  })
})

describe('RouteEntry — exported shape', () => {
  it('describes the structure of every registry element', () => {
    // Exercise the exported interface at both the type and runtime level.
    const pick = (e: RouteEntry): Array<keyof RouteEntry> =>
      (['path', 'name', 'label', 'i18nKey'] as Array<keyof RouteEntry>).filter(
        (k) => e[k] !== undefined,
      )

    const first = ROUTE_REGISTRY[0]
    expect(pick(first)).toEqual(['path', 'name', 'label', 'i18nKey'])

    const sample: RouteEntry = {
      path: '/example',
      name: 'Example',
      label: 'Example',
      i18nKey: 'routes.example',
    }
    expect(sample.hidden).toBeUndefined()
    expect(humanize(sample.name)).toBe(sample.label)
  })
})
